CREATE TABLE IF NOT EXISTS esc_synonym_point (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  code VARCHAR(180) NOT NULL,
  mode VARCHAR(16) NOT NULL COMMENT 'synonym/antonym',
  level_code VARCHAR(32) NOT NULL DEFAULT 'ket',
  source VARCHAR(64) NOT NULL DEFAULT '',
  section_name VARCHAR(128) NOT NULL DEFAULT '',
  left_text VARCHAR(1000) NOT NULL,
  left_cn VARCHAR(1000) DEFAULT '',
  right_text VARCHAR(1000) NOT NULL,
  right_cn VARCHAR(1000) DEFAULT '',
  sort INT NOT NULL DEFAULT 0,
  status TINYINT NOT NULL DEFAULT 1 COMMENT '0 draft, 1 published, 2 disabled',
  tenant_id BIGINT NOT NULL DEFAULT 0,
  creator VARCHAR(64) DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater VARCHAR(64) DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted BIT(1) NOT NULL DEFAULT 0,
  UNIQUE KEY uk_synonym_point_code (tenant_id, code, deleted),
  INDEX idx_synonym_point_pool (level_code, mode, status, sort)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Synonym and antonym knowledge points';

CREATE TABLE IF NOT EXISTS esc_user_synonym_progress (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  point_id BIGINT NOT NULL,
  seen_count INT NOT NULL DEFAULT 0,
  correct_count INT NOT NULL DEFAULT 0,
  wrong_count INT NOT NULL DEFAULT 0,
  mastered BIT(1) NOT NULL DEFAULT 0,
  last_answered_at DATETIME DEFAULT NULL,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  creator VARCHAR(64) DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater VARCHAR(64) DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted BIT(1) NOT NULL DEFAULT 0,
  UNIQUE KEY uk_user_synonym_progress (tenant_id, user_id, point_id, deleted),
  INDEX idx_user_synonym_progress_user (user_id, mastered, last_answered_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='User synonym practice progress';

CREATE TABLE IF NOT EXISTS esc_synonym_attempt (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  point_id BIGINT NOT NULL,
  answer_text VARCHAR(1000) NOT NULL,
  correct BIT(1) NOT NULL,
  duration_seconds INT DEFAULT NULL,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  creator VARCHAR(64) DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updater VARCHAR(64) DEFAULT '', update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted BIT(1) NOT NULL DEFAULT 0,
  INDEX idx_synonym_attempt_user (user_id, point_id, create_time),
  INDEX idx_synonym_attempt_point (point_id, create_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Synonym practice attempts';

SELECT '同义替换题库', '', 2, 44, 5047, 'synonym', '#', 'english/synonym/index', 0, b'1', b'1', b'1'
WHERE NOT EXISTS (SELECT 1 FROM system_menu WHERE parent_id = 5047 AND path = 'synonym' AND deleted = b'0');
SET @synonym_menu_id := (SELECT id FROM system_menu WHERE parent_id = 5047 AND path = 'synonym' AND deleted = b'0' ORDER BY id LIMIT 1);
SELECT p.name, p.permission, 3, p.sort, @synonym_menu_id, '', '#', NULL, 0, b'1', b'1', b'1'
FROM (
  SELECT '同义替换查询' name, 'english:synonym:query' permission, 1 sort
  UNION ALL SELECT '同义替换创建', 'english:synonym:create', 2
  UNION ALL SELECT '同义替换更新', 'english:synonym:update', 3
  UNION ALL SELECT '同义替换删除', 'english:synonym:delete', 4
) p WHERE NOT EXISTS (SELECT 1 FROM system_menu m WHERE m.permission = p.permission AND m.deleted = b'0');

-- Generated from local synonym books. Re-run extract_synonym_bank.py after source book changes.
ON DUPLICATE KEY UPDATE
  mode = VALUES(mode), level_code = VALUES(level_code), source = VALUES(source), section_name = VALUES(section_name), left_text = VALUES(left_text), left_cn = VALUES(left_cn), right_text = VALUES(right_text), right_cn = VALUES(right_cn), sort = VALUES(sort), status = VALUES(status);

